document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("theme-toggle"),t=localStorage.getItem("theme")||"light";"dark"===t&&document.body.classList.add("dark"),e&&e.addEventListener("click",function(){document.body.classList.toggle("dark"),localStorage.setItem("theme",document.body.classList.contains("dark")?"dark":"light")});document.querySelectorAll("form[data-validate]").forEach(function(e){e.addEventListener("submit",function(t){let n=!0;this.querySelectorAll("[required]").forEach(function(e){e.value.trim()||(n=!1,e.classList.add("invalid"))}),n||(--t.preventDefault(),alert("Please fill required fields."))})})});function setTheme(e){"dark"===e?document.body.classList.add("dark"):document.body.classList.remove("dark"),localStorage.setItem("theme",e)}
